    a,b=l.rstrip('\n').split('\t'); rows[int(a)]=b
abbr={'POSITIVE-VERIFIED':'PV','NEGATIVE-VERIFIED':'NV','NEGATIVE-BOUNDED':'NB','CONTESTED':'CT','RETIRED':'RET','FIXED':'FIXED','DUPLICATE':'DUP'}
testdirs=['ProjectFortress/compiler_tests','ProjectFortress/tests','ProjectFortress/compiler_regressions','ProjectFortress/library_tests','ProjectFortress/not_passing_yet','ProjectFortress/not_working_compiler_tests','ProjectFortress/other_compiler_tests','ProjectFortress/linker_tests','ProjectFortress/parser_tests']
def findtest(name):
    name=name.strip()
    base=re.sub(r'\.(fss|fsi|test)$','',name)
    base=base.split('/')[-1]
    out=[]
    if '*' in base:
        for d in testdirs:
            g=glob.glob(d+'/'+base+'.fss')+glob.glob(d+'/'+base+'.test')
            if g: out+=[x for x in g]
        return out
    for d in testdirs:
        for ext in ('.fss','.test','.fsi'):
            p=d+'/'+base+ext
            if os.path.exists(p): out.append(p)
    return out
def parserows(t):
    res=[]
    for m in re.finditer(r'\brows? (\d+(?:(?:, | and |, and | to )\d+)*)',t):
        s=m.group(1)
        if ' to ' in s and ',' not in s and ' and ' not in s:
            a,b=s.split(' to '); res+=range(int(a),int(b)+1)
        else:
            res+=[int(x) for x in re.findall(r'\d+',s)]
    return res
for i,t in enumerate(lines):
    n=73+i
    if not t.strip(): continue
    print('=== ',n)
    title=re.match(r'- \*\*(.*?)\*\*',t)
    # reports
    mds=[]
    for m in re.finditer(r'`([^`]+\.md)`',t):
        mds.append(m.group(1))
    for p in dict.fromkeys(mds):
        ok=None
        for pre in ['explorations/','explorations/coordinator/','']:
            if os.path.isfile(pre+p): ok=pre+p;break
        print('MD',p,'->',ok)
    r=parserows(t)
    r=list(dict.fromkeys(r))
    byst={}
    for x in r:
        byst.setdefault(abbr.get(rows.get(x,'MISSING'),'MISSING'),[]).append(x)
    print('ROWS',byst)
    # tests: backtick tokens after Gated by / refusal / expected failure
    gi=[m.start() for m in re.finditer(r'Gated by|gated by|expected failure|refusal',t)]
    tests=[]
    if gi:
        seg=t[min(gi):]
        for m in re.finditer(r'`([^`]+)`',seg): tests.append(m.group(1))
    found=0;missing=[]
    for x in dict.fromkeys(tests):
        if re.search(r'[\\|]|^\W',x) and not re.match(r'^(compiler_tests/|tests/)?[A-Za-z0-9_*]+(\.fss)?$',x): continue
        if x.startswith('…'): continue
        ff=findtest(x)
        if ff: found+=1
        else: missing.append(x)
    print('TESTS found',found,'notfound',missing)
