import re,sys
W=sys.argv[1]
def titles(f):
    out=[]
    for i,l in enumerate(open(f).read().split('\n'),1):
        m=re.match(r'- \*\*(.*?)\*\*',l)
        if m: out.append((i,m.group(1)))
    return out
P=titles(W+'/POSITIONS.md'); F=titles(W+'/FACTS.md')
print(len(P),len(F))
chunk=open(W+'/chunk.txt').read().split('\n')
def norm(s): return re.sub(r'\s+',' ',s.replace('…','...')).strip()
for i,t in enumerate(chunk):
    n=73+i
    if not t.strip(): continue
    qs=re.findall(r'"([^"]{8,}?)"',t)
    pos=[];fa=[];unk=[]
    for q in qs:
        qq=norm(q)
        qq=re.sub(r'\s*\.\.\.$','',qq); qq=re.sub(r'[.,]$','',qq)
        hp=[ln for ln,ti in P if norm(ti).startswith(qq) or qq in norm(ti)]
        hf=[ln for ln,ti in F if norm(ti).startswith(qq) or qq in norm(ti)]
        if hp: pos.append((q[:50],hp))
        elif hf: fa.append((q[:50],hf))
        else: unk.append(q[:60])
    print(n,'POS',pos,'| FACTS',fa,'| other',unk)
EOF
python3 $W/ex3.py $W

